const resetManualClientServiceDraft =
  () => {
    setManualClientServiceDraft({
      serviceDate: "",
      serviceTime: "",
      therapistName: "",
      serviceName: "",
      totalPrice: "",
    });

    setManualClientServiceSaveError(
      ""
    );
  };

const saveManualClientServiceHistory =
  async () => {
    if (
      !ensureSystemWritable() ||
      !canAddData
    ) {
      return;
    }

    if (!selectedClient?.id) {
      setManualClientServiceSaveError(
        "تعذر تحديد العميلة."
      );

      return;
    }

    const serviceDate =
      String(
        manualClientServiceDraft
          .serviceDate || ""
      ).trim();

    const serviceTime =
      String(
        manualClientServiceDraft
          .serviceTime || ""
      ).trim();

    const therapistName =
      String(
        manualClientServiceDraft
          .therapistName || ""
      ).trim();

    const serviceName =
      String(
        manualClientServiceDraft
          .serviceName || ""
      ).trim();

    const totalPriceText =
      String(
        manualClientServiceDraft
          .totalPrice || ""
      ).trim();

    const totalPrice =
      Number(
        totalPriceText.replace(
          ",",
          "."
        )
      );

    if (!serviceDate) {
      setManualClientServiceSaveError(
        "اختاري تاريخ الخدمة."
      );

      return;
    }

    if (
      serviceDate >
      currentDate
    ) {
      setManualClientServiceSaveError(
        "لا يمكن إضافة خدمة بتاريخ مستقبلي."
      );

      return;
    }

    if (!serviceName) {
      setManualClientServiceSaveError(
        "اكتبي اسم الخدمة."
      );

      return;
    }

    if (
      !totalPriceText ||
      !Number.isFinite(totalPrice) ||
      totalPrice < 0
    ) {
      setManualClientServiceSaveError(
        "أدخلي سعرًا صحيحًا شامل التوصيل."
      );

      return;
    }

    setManualClientServiceSaving(
      true
    );

    setManualClientServiceSaveError(
      ""
    );

    const {
      error,
    } = await supabase.rpc(
      "add_manual_legacy_client_service",
      {
        p_client_id:
          Number(
            selectedClient.id
          ),

        p_service_date:
          serviceDate,

        p_service_time:
          serviceTime,

        p_therapist_name:
          therapistName,

        p_service_name:
          serviceName,

        p_total_price:
          totalPrice,
      }
    );

    setManualClientServiceSaving(
      false
    );

    if (error) {
      console.error(
        "Manual client service save error:",
        error
      );

      setManualClientServiceSaveError(
        "تعذر حفظ الخدمة. تأكد من البيانات والاتصال."
      );

      return;
    }

    resetManualClientServiceDraft();

    setShowManualClientServiceForm(
      false
    );

    alert(
      "تمت إضافة الخدمة إلى سجل العميلة فقط."
    );
  };


useEffect(() => {
  if (
    !authReady ||
    !isLoggedIn ||
    !selectedClientId
  ) {
    setManualClientServiceHistory([]);
    setManualClientServiceHistoryLoading(false);
    setManualClientServiceHistoryError("");

    return undefined;
  }

  let effectActive = true;
  let realtimeReloadTimer = null;

  const normalizeManualService = (
    service,
    matchedInvoice = null
  ) => {
    const serviceSource =
      service.source || "manual_legacy";

    const invoiceId =
      service.invoice_id ||
      matchedInvoice?.id ||
      "";

    return {
      id: service.id,

      clientId:
        service.client_id,

      date:
        service.service_date || "",

      serviceTime:
        service.service_time || "",

      therapist:
        service.therapist_name || "-",

      services:
        service.service_name || "-",

      totalPrice:
        Number(
          service.total_price || 0
        ),

      serviceAmount:
        Number(
          service.total_price || 0
        ),

      transportation: 0,

      status:
        service.service_status || "",

      source:
        serviceSource,

      manualHistory:
        serviceSource !== "schedule",

      scheduleRowId:
        service.schedule_row_id || "",

      scheduleRowIndex:
        Number(
          service.schedule_row_index || 0
        ),

      scheduleItemKey:
        service.schedule_item_key || "",

      sourceKey:
        service.source_key || "",

      householdRole:
        service.household_role ||
        "primary",

      householdClientKey:
        service.household_client_key ||
        "",

      householdClient:
        service.household_role ===
        "additional",

      invoiceLink:
        invoiceId
          ? {
              invoiceId,
            }
          : null,

      createdAt:
        service.created_at || "",

      updatedAt:
        service.updated_at || "",
    };
  };

  const findInvoiceForService = (
    service,
    linkedInvoices
  ) => {
    if (service.invoice_id) {
      return {
        id: service.invoice_id,
      };
    }

    if (
      service.source !== "schedule" ||
      !service.schedule_row_id
    ) {
      return null;
    }

    const householdRole =
      service.household_role ||
      "primary";

    const householdClientKey =
      service.household_client_key ||
      "";

    const sameRowInvoices =
      linkedInvoices.filter(
        (invoice) =>
          String(
            invoice.schedule_row_id || ""
          ) ===
            String(
              service.schedule_row_id
            ) &&
          String(
            invoice.document_type ||
              "invoice"
          ) === "invoice"
      );

    if (householdRole === "primary") {
      return (
        sameRowInvoices.find(
          (invoice) =>
            String(
              invoice.household_role ||
                "primary"
            ) === "primary"
        ) || null
      );
    }

    const exactAdditionalInvoice =
      sameRowInvoices.find(
        (invoice) =>
          String(
            invoice.household_role || ""
          ) === "additional" &&
          String(
            invoice.household_client_key ||
              ""
          ) ===
            String(
              householdClientKey
            )
      );

    if (exactAdditionalInvoice) {
      return exactAdditionalInvoice;
    }

    const sameClientInvoices =
      sameRowInvoices.filter(
        (invoice) =>
          String(
            invoice.household_role || ""
          ) === "additional" &&
          String(
            invoice.client_id || ""
          ) ===
            String(
              service.client_id || ""
            )
      );

    return sameClientInvoices.length === 1
      ? sameClientInvoices[0]
      : null;
  };

  const loadManualClientServices =
    async () => {
      setManualClientServiceHistoryLoading(
        true
      );

      setManualClientServiceHistoryError(
        ""
      );

      const {
        data,
        error,
      } = await supabase
        .from(
          "client_service_history"
        )
        .select(
          [
            "id",
            "client_id",
            "service_date",
            "service_time",
            "therapist_name",
            "service_name",
            "total_price",
            "service_status",
            "source",
            "source_key",
            "invoice_id",
            "schedule_row_id",
            "schedule_row_index",
            "schedule_item_key",
            "household_role",
            "household_client_key",
            "created_at",
            "updated_at",
          ].join(",")
        )
        .eq(
          "client_id",
          selectedClientId
        )
        .order(
          "service_date",
          {
            ascending: true,
          }
        )
        .order(
          "created_at",
          {
            ascending: true,
          }
        );

      if (!effectActive) {
        return;
      }

      if (error) {
        console.error(
          "Client service history load error:",
          error
        );

        setManualClientServiceHistory(
          []
        );

        setManualClientServiceHistoryError(
          "تعذر تحميل سجل الخدمات."
        );

        setManualClientServiceHistoryLoading(
          false
        );

        return;
      }

      const historyRows =
        data || [];

      const scheduleRowIds = [
        ...new Set(
          historyRows
            .filter(
              (service) =>
                service.source ===
                  "schedule" &&
                service.schedule_row_id &&
                !service.invoice_id
            )
            .map(
              (service) =>
                service.schedule_row_id
            )
        ),
      ];

      let linkedInvoices = [];

      for (
        let startIndex = 0;
        startIndex <
        scheduleRowIds.length;
        startIndex += 100
      ) {
        const scheduleRowIdsBatch =
          scheduleRowIds.slice(
            startIndex,
            startIndex + 100
          );

        const {
          data: invoiceRows,
          error: invoiceLoadError,
        } = await supabase
          .from("invoices")
          .select(
            [
              "id",
              "document_type",
              "schedule_row_id",
              "household_role",
              "household_client_key",
              "client_id",
            ].join(",")
          )
          .in(
            "schedule_row_id",
            scheduleRowIdsBatch
          )
          .eq(
            "document_type",
            "invoice"
          );

        if (invoiceLoadError) {
          console.error(
            "Service history invoice links load error:",
            invoiceLoadError
          );

          break;
        }

        linkedInvoices = [
          ...linkedInvoices,
          ...(invoiceRows || []),
        ];
      }

      if (!effectActive) {
        return;
      }

      setManualClientServiceHistory(
        historyRows.map(
          (service) =>
            normalizeManualService(
              service,
              findInvoiceForService(
                service,
                linkedInvoices
              )
            )
        )
      );

      setManualClientServiceHistoryLoading(
        false
      );
    };

  const scheduleRealtimeReload = () => {
    if (realtimeReloadTimer) {
      clearTimeout(
        realtimeReloadTimer
      );
    }

    realtimeReloadTimer = setTimeout(
      () => {
        loadManualClientServices();
      },
      150
    );
  };

  const manualServicesChannel =
    supabase
      .channel(
        `client-service-history-${selectedClientId}`
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table:
            "client_service_history",
        },
        scheduleRealtimeReload
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "invoices",
        },
        scheduleRealtimeReload
      )
      .subscribe();

  loadManualClientServices();

  return () => {
    effectActive = false;

    if (realtimeReloadTimer) {
      clearTimeout(
        realtimeReloadTimer
      );
    }

    supabase.removeChannel(
      manualServicesChannel
    );
  };
}, [
  authReady,
  isLoggedIn,
  selectedClientId,
]);


