const normalizeClientRecord = (client) => ({
  ...client,
  id: client.id,
  name: client.name || client.arabic_name || "",
  arabic_name: client.arabic_name || client.name || "",

  loyaltyCardName:
    client.loyalty_card_name || "",

  phone: client.phone || "",
  address: client.address || "",
  visits: Number(client.visits || 0),
  frame: Boolean(client.frame),
  blacklist: Boolean(client.blacklist),
  notes: client.notes || "",
  last_order_at: client.last_order_at || "",
  last_activity_at: client.last_activity_at || "",
  last_contacted_at: client.last_contacted_at || "",
  referrals: Array.isArray(client.referrals)
    ? client.referrals
    : [],
});

const CLIENTS_CACHE_KEY = "paradise-clients-cache";
const CLIENTS_CACHE_MAX_AGE = 30 * 60 * 1000;

const loadClientsFromCache = () => {
  try {
    const cached = JSON.parse(localStorage.getItem(CLIENTS_CACHE_KEY) || "null");

    if (!cached?.savedAt || !Array.isArray(cached.clients)) return false;

    const cacheAge = Date.now() - Number(cached.savedAt);

    if (cacheAge > CLIENTS_CACHE_MAX_AGE) return false;

    setClientsSafely(cached.clients, false);
    return true;
  } catch {
    return false;
  }
};

const saveClientsToCache = (nextClients) => {
  try {
    localStorage.setItem(
      CLIENTS_CACHE_KEY,
      JSON.stringify({
        savedAt: Date.now(),
        clients: nextClients || [],
      })
    );
  } catch (error) {
    console.log("Clients cache save error:", error);
  }
};

const setClientsSafely = (nextClients, saveCache = true) => {
  const normalizedClients = Array.isArray(nextClients)
    ? nextClients.map(normalizeClientRecord)
    : [];

  setClients(normalizedClients);

  if (saveCache) {
    saveClientsToCache(normalizedClients);
  }
};

async function fetchClientsWithSupabaseClient() {
  const pageSize = 1000;
  let allClients = [];
  let from = 0;
  let hasMore = true;

  while (hasMore) {
    const to = from + pageSize - 1;
    const { data, error } = await supabase
      .from("clients")
      .select(
        "id,name,arabic_name,loyalty_card_name,phone,address,visits,frame,blacklist,notes,last_order_at,last_activity_at,last_contacted_at"
      )
      .order("id", { ascending: false })
      .range(from, to);

    if (error) {
      throw error;
    }

    const pageData = data || [];
    allClients = [...allClients, ...pageData];
    hasMore = pageData.length === pageSize;
    from += pageSize;
  }

  return allClients;
}

async function fetchClientsWithRestApi() {
  const {
    data: sessionData,
    error: sessionError,
  } = await supabase.auth.getSession();

  const accessToken =
    sessionData?.session?.access_token;

  if (
    sessionError ||
    !accessToken
  ) {
    throw new Error(
      "Authenticated session is required for clients REST fetch"
    );
  }

  const pageSize = 1000;
  let allClients = [];
  let offset = 0;
  let hasMore = true;

  while (hasMore) {
    const response = await fetch(
      `${supabaseUrl}/rest/v1/clients?select=id,name,arabic_name,loyalty_card_name,phone,address,visits,frame,blacklist,notes,last_order_at,last_activity_at,last_contacted_at&order=id.desc&limit=${pageSize}&offset=${offset}`,
      {
        headers: {
          apikey: supabaseKey,
          Authorization: `Bearer ${accessToken}`,
        },
      }
    );

    if (!response.ok) {
      throw new Error(
        `REST clients fetch failed: ${response.status}`
      );
    }

    const pageData =
      await response.json();

    allClients = [
      ...allClients,
      ...(pageData || []),
    ];

    hasMore =
      Array.isArray(pageData) &&
      pageData.length === pageSize;

    offset += pageSize;
  }

  return allClients;
}

async function fetchClients() {
  try {
    const allClients = await fetchClientsWithSupabaseClient();

    if (allClients.length > 0) {
      setClientsSafely(allClients);
      return;
    }

    const restClients = await fetchClientsWithRestApi();
    setClientsSafely(restClients);
  } catch (error) {
    console.log("Clients fetch error, trying REST fallback:", error);

    try {
      const restClients = await fetchClientsWithRestApi();
      setClientsSafely(restClients);
    } catch (restError) {
      console.log("Clients REST fallback fetch error:", restError);
      setClientsSafely([]);
    }
  }
}
