  const [restoreFileName, setRestoreFileName] = useState("");
  const [manualExcelMonth, setManualExcelMonth] = useState(() => getCurrentLocalDate().slice(0, 7));

  const sharedDataKeys = [
  "scheduleSettings",
  "financeMonthlySettings",
];

  const sharedDataLocalStorageKeys = {
    dailyManualData: "paradise-daily-manual-data",
    scheduleSettings: "paradise-schedule-settings",
    financeMonthlySettings: "paradise-finance-monthly-settings",
  };

  const getSharedDataLocalStorageKey = (dataKey) =>
    sharedDataLocalStorageKeys[dataKey] || `paradise-${dataKey}`;

  const getSharedDataMetaKey = (dataKey) => `${dataKey}Meta`;

  const getSharedDataBackupKey = (dataKey) => `${dataKey}Backup`;

  const getSharedDataLastEditTime = (dataKey) => {
    if (dataKey === "scheduleData") return scheduleLastEditRef.current;
    if (dataKey === "dailyManualData") return dailyManualLastEditRef.current;
    if (dataKey === "scheduleSettings") return scheduleSettingsLastEditRef.current;
    if (dataKey === "financeMonthlySettings") return financeSettingsLastEditRef.current;
    return 0;
  };

  const saveSharedDataLocalBackup = (dataKey, dataValue, source) => {
    try {
      const backupRecord = {
        source,
        savedAt: new Date().toISOString(),
        data: dataValue,
      };
      const storageKey = getSharedDataLocalStorageKey(dataKey);

      localStorage.setItem(
        `${storageKey}-backup-latest`,
        JSON.stringify(backupRecord)
      );
    } catch (backupError) {
      console.log("Shared data local backup error:", backupError);
    }
  };

  const saveSharedData = async (dataKey, dataValue) => {
    if (!sharedDataKeys.includes(dataKey)) return;

    saveSharedDataLocalBackup(
      dataKey,
      dataValue,
      "before-save-local"
    );

    const metaKey =
      getSharedDataMetaKey(dataKey);

    const backupKey =
      getSharedDataBackupKey(dataKey);

    const {
      data: existingRows,
      error: loadError,
    } = await supabase
      .from("app_data")
      .select("data_key, data")
      .in(
        "data_key",
        [dataKey, metaKey]
      );

    if (loadError) {
      console.log(
        "Shared data pre-save check error:",
        loadError
      );

      return;
    }

    const existingDataRow =
      existingRows?.find(
        (row) =>
          row.data_key === dataKey
      );

    const existingMetaRow =
      existingRows?.find(
        (row) =>
          row.data_key === metaKey
      );

    const remoteData =
      existingDataRow?.data;

    const remoteMeta =
      existingMetaRow?.data || {};

    const knownMeta =
      sharedDataMetaRef.current[
        dataKey
      ] || {};

    const remoteUpdatedAt =
      Number(
        remoteMeta.updatedAt || 0
      );

    const knownUpdatedAt =
      Number(
        knownMeta.updatedAt || 0
      );

    const remoteDeviceId =
      remoteMeta.deviceId || "";

    const localLastEditAt =
      Number(
        getSharedDataLastEditTime(
          dataKey
        ) || 0
      );

    const remoteDataMatchesLocal =
      JSON.stringify(
        remoteData ?? null
      ) ===
      JSON.stringify(
        dataValue ?? null
      );

    if (remoteDataMatchesLocal) {
      sharedDataMetaRef.current[
        dataKey
      ] = remoteMeta;

      return;
    }

    const remoteDataIsNewer =
      remoteUpdatedAt >
      knownUpdatedAt;

    const remoteCameFromAnotherDevice =
      Boolean(remoteDeviceId) &&
      remoteDeviceId !==
        sharedDataDeviceIdRef.current;

    const localEditIsNotNewer =
      localLastEditAt <=
      remoteUpdatedAt;

    if (
      remoteDataIsNewer &&
      remoteCameFromAnotherDevice &&
      localEditIsNotNewer
    ) {
      sharedDataMetaRef.current[
        dataKey
      ] = remoteMeta;

      saveSharedDataLocalBackup(
        dataKey,
        dataValue,
        "blocked-stale-overwrite"
      );

      console.log(
        `Blocked stale ${dataKey} save to protect newer Supabase data. Refresh/load the latest data before saving again.`
      );

      return;
    }

    const nextMeta = {
      dataKey,

      updatedAt:
        Date.now(),

      updatedAtIso:
        new Date().toISOString(),

      deviceId:
        sharedDataDeviceIdRef.current,

      lastLocalEditAt:
        localLastEditAt,
    };

    const { error } =
      await supabase
        .from("app_data")
        .upsert(
          {
            data_key:
              dataKey,

            data:
              dataValue,
          },
          {
            onConflict:
              "data_key",
          }
        );

    if (error) {
      console.log(
        "Shared data save error:",
        error
      );

      return;
    }

    const {
      error: metaError,
    } = await supabase
      .from("app_data")
      .upsert(
        {
          data_key:
            metaKey,

          data:
            nextMeta,
        },
        {
          onConflict:
            "data_key",
        }
      );

    if (metaError) {
      console.log(
        "Shared data meta save error:",
        metaError
      );

      return;
    }

    sharedDataMetaRef.current[
      dataKey
    ] = nextMeta;

    saveSharedDataLocalBackup(
      dataKey,
      dataValue,
      "after-save-success"
    );
  };

  const loadSharedData = async () => {
    const keysToLoad = [
      ...sharedDataKeys,
      ...sharedDataKeys.map(getSharedDataMetaKey),
    ];

    const { data, error } = await supabase
      .from("app_data")
      .select("data_key, data")
      .in("data_key", keysToLoad);

    if (error) {
      console.log("Shared data load error:", error);
      setSharedDataLoaded(true);
      return;
    }

    
    const settingsRow = data?.find((row) => row.data_key === "scheduleSettings");
    const financeSettingsRow = data?.find((row) => row.data_key === "financeMonthlySettings");

    sharedDataKeys.forEach((dataKey) => {
      const metaRow = data?.find((row) => row.data_key === getSharedDataMetaKey(dataKey));
      if (metaRow?.data) {
        sharedDataMetaRef.current[dataKey] = metaRow.data;
      }
    });

    const now = Date.now();
    const userIsEditingSharedData = isSharedDataInputFocused();
    
    const recentlyEditedScheduleSettings =
      userIsEditingSharedData ||
      now - scheduleSettingsLastEditRef.current < sharedDataEditProtectionDelay;
    const recentlyEditedFinanceSettings =
      userIsEditingSharedData ||
      now - financeSettingsLastEditRef.current < sharedDataEditProtectionDelay;

    

    if (settingsRow?.data && !recentlyEditedScheduleSettings) {
      setScheduleSettings(settingsRow.data);
      localStorage.setItem("paradise-schedule-settings", JSON.stringify(settingsRow.data));
      saveSharedDataLocalBackup("scheduleSettings", settingsRow.data, "after-load-supabase");
    }

    if (financeSettingsRow?.data && !recentlyEditedFinanceSettings) {
      setFinanceMonthlySettings(financeSettingsRow.data);
      localStorage.setItem(
        "paradise-finance-monthly-settings",
        JSON.stringify(financeSettingsRow.data)
      );
      saveSharedDataLocalBackup(
        "financeMonthlySettings",
        financeSettingsRow.data,
        "after-load-supabase"
      );
    }

    setSharedDataLoaded(true);
  };

  useEffect(() => {
    if (!isLoggedIn) return;

    loadSharedData();

    const appDataPolling = setInterval(() => {
      loadSharedData();
    }, 86400000);

    const appDataChannel = supabase
  .channel("app-data-sync")
  .on(
    "postgres_changes",
    {
      event: "*",
      schema: "public",
      table: "app_data",
    },
    (payload) => {
      const changedKey = payload?.new?.data_key || payload?.old?.data_key || "";
      const changedData = payload?.new?.data;

      if (!sharedDataKeys.includes(changedKey)) return;
      if (!changedData) return;

      const now = Date.now();
      const userIsEditingSharedData = isSharedDataInputFocused();

     

      if (
        changedKey === "scheduleSettings" &&
        !userIsEditingSharedData &&
        now - scheduleSettingsLastEditRef.current >= sharedDataEditProtectionDelay
      ) {
        setScheduleSettings(changedData);
        localStorage.setItem("paradise-schedule-settings", JSON.stringify(changedData));
        saveSharedDataLocalBackup("scheduleSettings", changedData, "after-realtime-direct");
      }

      if (
        changedKey === "financeMonthlySettings" &&
        !userIsEditingSharedData &&
        now - financeSettingsLastEditRef.current >= sharedDataEditProtectionDelay
      ) {
        setFinanceMonthlySettings(changedData);
        localStorage.setItem(
          "paradise-finance-monthly-settings",
          JSON.stringify(changedData)
        );
        saveSharedDataLocalBackup(
          "financeMonthlySettings",
          changedData,
          "after-realtime-direct"
        );
      }
    }
  )
  .subscribe();

    return () => {
      clearInterval(appDataPolling);
      supabase.removeChannel(appDataChannel);
    };
  }, [isLoggedIn]);


  // 💾 SCHEDULE DATA
  // الجدول لا ينحفظ في localStorage ولا app_data.
  // الحفظ الحقيقي للمواعيد يتم فقط داخل schedule_rows، صف بصف.
const loadDailyReportForDate = async (date) => {
  if (!date) return;

  const { data, error } = await supabase
    .from("daily_reports")
    .select("report_date, report_data, updated_at, updated_by")
    .eq("report_date", date)
    .maybeSingle();

  if (error) {
    console.log("Daily report load error:", error);
    return;
  }

  if (data?.report_data) {
    setDailyManualData((prev) => ({
      ...prev,
      [date]: data.report_data,
    }));
  }
};

const saveDailyReportForDate = async (date, reportData) => {
  if (!date) return;

  const { error } = await supabase.from("daily_reports").upsert(
    {
      report_date: date,
      report_data: reportData || {},
      updated_at: new Date().toISOString(),
      updated_by: sharedDataDeviceIdRef.current,
    },
    { onConflict: "report_date" }
  );

  if (error) {
    console.log("Daily report save error:", error);
  }
};

const queueDailyReportSave = (date, reportData) => {
  if (!date) return;

  if (dailyReportSaveTimersRef.current[date]) {
    clearTimeout(dailyReportSaveTimersRef.current[date]);
  }

  dailyReportSaveTimersRef.current[date] = setTimeout(() => {
    saveDailyReportForDate(date, reportData);
    delete dailyReportSaveTimersRef.current[date];
  }, 700);
};

useEffect(() => {
  localStorage.setItem(
    "paradise-daily-manual-data",
    JSON.stringify(dailyManualData)
  );
}, [dailyManualData]);

useEffect(() => {
  if (!isLoggedIn || !selectedScheduleDate) return undefined;

  loadDailyReportForDate(selectedScheduleDate);

  const dailyReportsChannel = supabase
    .channel("daily-reports-sync")
    .on(
  "postgres_changes",
  {
    event: "*",
    schema: "public",
    table: "daily_reports",
  
  },
      (payload) => {
        if (payload.eventType === "DELETE") {
          const removedDate = payload.old?.report_date;
          if (!removedDate) return;

          setDailyManualData((prev) => {
            const next = { ...prev };
            delete next[removedDate];
            return next;
          });
          return;
        }

        const record = payload.new;
        const reportDate = record?.report_date;

        if (!reportDate) return;
        if (record?.updated_by === sharedDataDeviceIdRef.current) return;

        const now = Date.now();
        const userIsEditingSharedData = isSharedDataInputFocused();

        if (
          reportDate === selectedScheduleDate &&
          userIsEditingSharedData &&
          now - dailyManualLastEditRef.current < sharedDataEditProtectionDelay
        ) {
          return;
        }

        setDailyManualData((prev) => ({
          ...prev,
          [reportDate]: record.report_data || {},
        }));
      }
    )
    .subscribe();

  return () => {
    supabase.removeChannel(dailyReportsChannel);
  };
}, [isLoggedIn, selectedScheduleDate]);


useEffect(() => {
  if (
    !isLoggedIn ||
    screen !== "appointments" ||
    !selectedScheduleDate
  ) {
    return undefined;
  }

  let effectActive = true;

  const loadDailyPurchases = async () => {
    setPurchasesLoading(true);
    setPurchasesError("");

    try {
      const { data, error } = await supabase
        .from("purchases")
        .select(
          [
            "id",
            "purchase_date",
            "product_name",
            "quantity",
            "total_price",
            "supplier_name",
            "vat_invoice",
            "vat_amount",
            "unit_price",
            "created_by",
            "created_at",
            "updated_at",
          ].join(",")
        )
        .eq(
          "purchase_date",
          selectedScheduleDate
        )
        .order("id", {
          ascending: false,
        });

      if (error) {
        throw error;
      }

      if (!effectActive) return;

      setPurchases(
        sortPurchaseRecordsNewestFirst(
          (data || []).map(
            normalizePurchaseRecord
          )
        )
      );
    } catch (error) {
      console.error(
        "Daily purchases load error:",
        error
      );

      if (effectActive) {
        setPurchasesError(
          "تعذر تحميل مشتريات هذا اليوم."
        );
      }
    } finally {
      if (effectActive) {
        setPurchasesLoading(false);
      }
    }
  };

  const dailyPurchasesChannel =
    supabase
      .channel(
        `purchases-daily-sync-${selectedScheduleDate}`
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "purchases",
        },
        (payload) => {
          if (
            payload.eventType ===
            "DELETE"
          ) {
            const removedPurchaseId =
              payload.old?.id;

            if (!removedPurchaseId) {
              return;
            }

            setPurchases(
              (previousPurchases) =>
                previousPurchases.filter(
                  (purchase) =>
                    String(
                      purchase.id
                    ) !==
                    String(
                      removedPurchaseId
                    )
                )
            );

            return;
          }

          if (!payload.new) return;

          const nextPurchase =
            normalizePurchaseRecord(
              payload.new
            );

          if (
            nextPurchase.purchaseDate !==
            selectedScheduleDate
          ) {
            return;
          }

          setPurchases(
            (previousPurchases) =>
              sortPurchaseRecordsNewestFirst([
                ...previousPurchases.filter(
                  (purchase) =>
                    String(
                      purchase.id
                    ) !==
                    String(
                      nextPurchase.id
                    )
                ),
                nextPurchase,
              ])
          );
        }
      )
      .subscribe((status) => {
        if (
          status === "CHANNEL_ERROR" ||
          status === "TIMED_OUT"
        ) {
          console.error(
            "Daily purchases realtime error:",
            status
          );
        }
      });

  loadDailyPurchases();

  return () => {
    effectActive = false;

    supabase.removeChannel(
      dailyPurchasesChannel
    );
  };
}, [
  isLoggedIn,
  screen,
  selectedScheduleDate,
]);


useEffect(() => {
  if (
    !isLoggedIn ||
    screen !== "appointments" ||
    !selectedScheduleDate ||
    purchasesLoading
  ) {
    return undefined;
  }

  let effectActive = true;

  const syncDailyPurchaseTotal =
    async () => {
      const dailyPurchases =
        purchases.filter(
          (purchase) =>
            purchase.purchaseDate ===
            selectedScheduleDate
        );

      const purchaseTotal = Number(
        dailyPurchases
          .reduce(
            (total, purchase) =>
              total +
              Number(
                purchase.totalPrice || 0
              ),
            0
          )
          .toFixed(2)
      );

      const {
        data: existingReport,
        error: reportLoadError,
      } = await supabase
        .from("daily_reports")
        .select("report_data")
        .eq(
          "report_date",
          selectedScheduleDate
        )
        .maybeSingle();

      if (
        reportLoadError ||
        !effectActive
      ) {
        if (reportLoadError) {
          console.error(
            "Purchase total report load error:",
            reportLoadError
          );
        }

        return;
      }

      const currentReport = {
        ...getManualForDate(
          selectedScheduleDate
        ),
        ...(existingReport?.report_data ||
          {}),
      };

      const purchaseIsManagedByTable =
        Boolean(
          currentReport
            .purchaseManagedByTable
        );

      if (
        dailyPurchases.length === 0 &&
        !purchaseIsManagedByTable
      ) {
        return;
      }

      const currentPurchaseTotal =
        Number(
          parseAmount(
            currentReport.purchase
          ).toFixed(2)
        );

      if (
        purchaseIsManagedByTable &&
        currentPurchaseTotal ===
          purchaseTotal
      ) {
        return;
      }

      const nextReport = {
        ...currentReport,

        purchase:
          purchaseTotal.toFixed(2),

        purchaseManagedByTable: true,
      };

      setDailyManualData(
        (previous) => ({
          ...previous,

          [selectedScheduleDate]:
            nextReport,
        })
      );

      await saveDailyReportForDate(
        selectedScheduleDate,
        nextReport
      );
    };

  syncDailyPurchaseTotal();

  return () => {
    effectActive = false;
  };
}, [
  isLoggedIn,
  screen,
  selectedScheduleDate,
  purchases,
  purchasesLoading,
]);


  // 💾 SAVE SCHEDULE SETTINGS
  useEffect(() => {
    localStorage.setItem(
      "paradise-schedule-settings",
      JSON.stringify(scheduleSettings)
    );

    if (!sharedDataLoaded) return undefined;

    const saveTimer = setTimeout(() => {
      saveSharedData("scheduleSettings", scheduleSettings);
    }, sharedDataSaveDelay);

    return () => clearTimeout(saveTimer);
  }, [scheduleSettings, sharedDataLoaded]);

  // 💾 SAVE FINANCE MONTHLY SETTINGS
  useEffect(() => {
    localStorage.setItem(
      "paradise-finance-monthly-settings",
      JSON.stringify(financeMonthlySettings)
    );

    if (!sharedDataLoaded) return undefined;

    const saveTimer = setTimeout(() => {
      saveSharedData("financeMonthlySettings", financeMonthlySettings);
    }, sharedDataSaveDelay);

    return () => clearTimeout(saveTimer);
  }, [financeMonthlySettings, sharedDataLoaded]);

  useEffect(() => {
    const updateTodayDate = () => {
      const newToday = getCurrentLocalDate();
      setCurrentDate((previousDate) => {
        if (previousDate !== newToday) {
          setSelectedScheduleDate(newToday);
        }
        return newToday;
      });
    };

    updateTodayDate();
    const dateTimer = setInterval(updateTodayDate, 60000);

    return () => clearInterval(dateTimer);
  }, []);


