const getInvoiceDateInRiyadh = (
  invoice
) => {
  const issuedAt =
    String(
      invoice?.issuedAt || ""
    ).trim();

  if (!issuedAt) {
    return "";
  }

  const issuedDate =
    new Date(issuedAt);

  if (
    Number.isNaN(
      issuedDate.getTime()
    )
  ) {
    return "";
  }

  const dateParts =
    new Intl.DateTimeFormat(
      "en-US",
      {
        timeZone:
          "Asia/Riyadh",
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
      }
    ).formatToParts(
      issuedDate
    );

  const datePartMap =
    dateParts.reduce(
      (result, part) => {
        if (
          part.type !==
          "literal"
        ) {
          result[part.type] =
            part.value;
        }

        return result;
      },
      {}
    );

  return [
    datePartMap.year,
    datePartMap.month,
    datePartMap.day,
  ].join("-");
};


const isInvoiceInsideDateRange = (
  invoice,
  fromDate,
  toDate
) => {
  const invoiceDate =
    getInvoiceDateInRiyadh(
      invoice
    );

  if (!invoiceDate) {
    return false;
  }

  if (
    fromDate &&
    invoiceDate < fromDate
  ) {
    return false;
  }

  if (
    toDate &&
    invoiceDate > toDate
  ) {
    return false;
  }

  return true;
};


const mergeInvoicesById = (
  currentInvoices,
  nextInvoices
) => {
  const invoiceMap = new Map();

  [
    ...(currentInvoices || []),
    ...(nextInvoices || []),
  ].forEach((invoice) => {
    if (!invoice?.id) return;

    invoiceMap.set(
      String(invoice.id),
      invoice
    );
  });

  return Array.from(
    invoiceMap.values()
  ).sort(
    (firstInvoice, secondInvoice) =>
      Number(
        secondInvoice.invoiceNumber || 0
      ) -
      Number(
        firstInvoice.invoiceNumber || 0
      )
  );
};


useEffect(() => {
  if (
    !isLoggedIn ||
    screen !== "invoices"
  ) {
    return undefined;
  }

  let effectActive = true;

  const loadInvoicesForSelectedRange =
    async () => {
      setInvoicesLoading(true);
      setInvoicesError("");

      try {
        const pageSize = 1000;
        let fromIndex = 0;
        let hasMore = true;
        let loadedInvoices = [];

        while (
          hasMore &&
          effectActive
        ) {
          const toIndex =
            fromIndex +
            pageSize -
            1;

          const {
            data,
            error,
          } = await supabase
            .from("invoices")
            .select(
              [
                "id",
                "invoice_number",
                "invoice_code",
                "document_type",
                "status",
                "source_service_key",
                "schedule_row_id",
                "schedule_date",
                "schedule_row_index",
                "household_role",
                "household_client_key",
                "client_id",
                "client_name",
                "client_phone",
                "service_name",
                "service_time",
                "payment_method",
                "service_amount_including_vat",
                "transportation_amount_including_vat",
                "total_including_vat",
                "subtotal_excluding_vat",
                "vat_rate",
                "vat_amount",
                "issued_at",
                "original_invoice_id",
                "correction_reason",
                "created_at",
                "updated_at",
              ].join(",")
            )
            .gte(
              "issued_at",
              `${invoicesFromDate}T00:00:00+03:00`
            )
            .lt(
              "issued_at",
              new Date(
                new Date(
                  `${invoicesToDate}T00:00:00+03:00`
                ).getTime() +
                  24 * 60 * 60 * 1000
              ).toISOString()
            )
            .order(
              "invoice_number",
              {
                ascending: false,
              }
            )
            .range(
              fromIndex,
              toIndex
            );

          if (error) {
            throw error;
          }

          const normalizedPage =
            (data || []).map(
              normalizeInvoiceRecord
            );

          loadedInvoices = [
            ...loadedInvoices,
            ...normalizedPage,
          ];

          hasMore =
            normalizedPage.length ===
            pageSize;

          fromIndex += pageSize;
        }

        if (!effectActive) return;

        setInvoices((previousInvoices) => {
          const currentRangeInvoices =
            previousInvoices.filter(
              (invoice) =>
                isInvoiceInsideDateRange(
                  invoice,
                  invoicesFromDate,
                  invoicesToDate
                )
            );

          return mergeInvoicesById(
            currentRangeInvoices,
            loadedInvoices
          );
        });

        setInvoicesVisibleCount(20);
      } catch (error) {
        console.error(
          "Invoices load error:",
          error
        );

        if (effectActive) {
          setInvoicesError(
            "تعذر تحميل المستندات. تأكد من الاتصال وحاول مرة أخرى."
          );
        }
      } finally {
        if (effectActive) {
          setInvoicesLoading(false);
        }
      }
    };

  const invoicesChannel =
    supabase
      .channel(
        "invoices-page-sync"
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "invoices",
        },
        (payload) => {
          if (
            payload.eventType ===
            "DELETE"
          ) {
            const removedInvoiceId =
              payload.old?.id;

            if (!removedInvoiceId) {
              return;
            }

            setInvoices(
              (previousInvoices) =>
                previousInvoices.filter(
                  (invoice) =>
                    String(invoice.id) !==
                    String(
                      removedInvoiceId
                    )
                )
            );

            return;
          }

          if (!payload.new) return;

          const nextInvoice =
            normalizeInvoiceRecord(
              payload.new
            );

          setInvoices(
            (previousInvoices) => {
              const withoutChangedInvoice =
                previousInvoices.filter(
                  (invoice) =>
                    String(invoice.id) !==
                    String(
                      nextInvoice.id
                    )
                );

              if (
                !isInvoiceInsideDateRange(
                  nextInvoice,
                  invoicesFromDate,
                  invoicesToDate
                )
              ) {
                return withoutChangedInvoice;
              }

              return mergeInvoicesById(
                withoutChangedInvoice,
                [nextInvoice]
              );
            }
          );

          setSelectedInvoice(
            (currentInvoice) =>
              String(
                currentInvoice?.id || ""
              ) ===
              String(
                nextInvoice.id
              )
                ? nextInvoice
                : currentInvoice
          );
        }
      )
      .subscribe(
        (status) => {
          if (
            status ===
            "CHANNEL_ERROR"
          ) {
            console.error(
              "Invoices realtime channel error"
            );
          }

          if (
            status ===
            "TIMED_OUT"
          ) {
            console.error(
              "Invoices realtime channel timed out"
            );
          }
        }
      );

  loadInvoicesForSelectedRange();

  return () => {
    effectActive = false;

    supabase.removeChannel(
      invoicesChannel
    );
  };
}, [
  isLoggedIn,
  screen,
  invoicesFromDate,
  invoicesToDate,
]);


