const calculatePurchaseVatAmount = (
  totalPrice
) => {
  const safeTotalPrice =
    Number(totalPrice || 0);

  if (
    !Number.isFinite(safeTotalPrice) ||
    safeTotalPrice <= 0
  ) {
    return 0;
  }

  return Number(
    (
      (safeTotalPrice * 15) /
      115
    ).toFixed(2)
  );
};


const calculatePurchaseUnitPrice = (
  totalPrice,
  quantity
) => {
  const safeTotalPrice =
    Number(totalPrice || 0);

  const safeQuantity =
    Number(quantity || 0);

  if (
    !Number.isFinite(safeTotalPrice) ||
    !Number.isFinite(safeQuantity) ||
    safeQuantity <= 0
  ) {
    return 0;
  }

  return Number(
    (
      safeTotalPrice /
      safeQuantity
    ).toFixed(2)
  );
};


const formatPurchasePageDate = (
  value
) => {
  const cleanDate =
    String(value || "").slice(
      0,
      10
    );

  if (!cleanDate) {
    return "-";
  }

  const [
    year,
    month,
    day,
  ] = cleanDate.split("-");

  return (
    year &&
    month &&
    day
  )
    ? `${day}-${month}-${year}`
    : cleanDate;
};


const formatPurchaseQuantity = (
  value
) => {
  const numericValue =
    Number(value || 0);

  if (
    !Number.isFinite(numericValue)
  ) {
    return "0";
  }

  return numericValue.toLocaleString(
    "en-US",
    {
      maximumFractionDigits: 3,
    }
  );
};


const sortPurchaseRecordsNewestFirst = (
  purchaseRows
) =>
  [...(purchaseRows || [])].sort(
    (
      firstPurchase,
      secondPurchase
    ) => {
      const dateComparison =
        String(
          secondPurchase.purchaseDate || ""
        ).localeCompare(
          String(
            firstPurchase.purchaseDate || ""
          )
        );

      if (dateComparison !== 0) {
        return dateComparison;
      }

      return (
        Number(
          secondPurchase.id || 0
        ) -
        Number(
          firstPurchase.id || 0
        )
      );
    }
  );


const upsertPurchaseInState = (
  nextPurchase
) => {
  if (!nextPurchase?.id) return;

  setPurchases(
    (previousPurchases) =>
      sortPurchaseRecordsNewestFirst([
        ...previousPurchases.filter(
          (purchase) =>
            String(purchase.id) !==
            String(nextPurchase.id)
        ),
        nextPurchase,
      ])
  );
};


const resetPurchaseDraft = () => {
  setPurchaseDraft({
    productName: "",
    quantity: "1",
    totalPrice: "",
    supplierName: "",
    vatInvoice: false,
  });
};


const createPurchase = async (
  purchaseDate = selectedScheduleDate
) => {
  if (
    !ensureSystemWritable() ||
    !canAddData ||
    purchaseSaving
  ) {
    return;
  }

  const productName =
    String(
      purchaseDraft.productName || ""
    ).trim();

  const supplierName =
    String(
      purchaseDraft.supplierName || ""
    ).trim();

  const quantity =
    Number(
      purchaseDraft.quantity
    );

  const totalPrice =
    Number(
      purchaseDraft.totalPrice
    );

  const safePurchaseDate =
    purchaseDate ||
    selectedScheduleDate ||
    getCurrentLocalDate();

  if (!productName) {
    alert(
      "اكتب اسم المنتج أولاً."
    );

    return;
  }

  if (
    !Number.isFinite(quantity) ||
    quantity <= 0
  ) {
    alert(
      "الكمية يجب أن تكون أكبر من صفر."
    );

    return;
  }

  if (
    !Number.isFinite(totalPrice) ||
    totalPrice <= 0
  ) {
    alert(
      "السعر الإجمالي يجب أن يكون أكبر من صفر."
    );

    return;
  }

  setPurchaseSaving(true);
  setPurchasesError("");

  try {
    const {
      data,
      error,
    } = await supabase
      .from("purchases")
      .insert([
        {
          purchase_date:
            safePurchaseDate,

          product_name:
            productName,

          quantity,

          total_price:
            totalPrice,

          supplier_name:
            supplierName,

          vat_invoice:
            Boolean(
              purchaseDraft.vatInvoice
            ),
        },
      ])
      .select(
        [
          "id",
          "purchase_date",
          "product_name",
          "quantity",
          "total_price",
          "supplier_name",
          "vat_invoice",
          "vat_amount",
          "unit_price",
          "created_by",
          "created_at",
          "updated_at",
        ].join(",")
      )
      .single();

    if (error) {
      throw error;
    }

    if (data) {
      upsertPurchaseInState(
        normalizePurchaseRecord(data)
      );
    }

    resetPurchaseDraft();
  } catch (error) {
    console.error(
      "Purchase create error:",
      error
    );

    setPurchasesError(
      "تعذر حفظ عملية الشراء."
    );

    alert(
      "لم يتم حفظ عملية الشراء. تأكد من الاتصال وحاول مرة أخرى."
    );
  } finally {
    setPurchaseSaving(false);
  }
};


const startEditPurchase = (
  purchase
) => {
  if (
    !purchase ||
    !canEditData ||
    !ensureSystemWritable()
  ) {
    return;
  }

  setEditingPurchaseId(
    purchase.id
  );

  setEditingPurchaseDraft({
    productName:
      purchase.productName || "",

    quantity:
      String(
        purchase.quantity || 1
      ),

    totalPrice:
      String(
        purchase.totalPrice || ""
      ),

    supplierName:
      purchase.supplierName || "",

    vatInvoice:
      Boolean(
        purchase.vatInvoice
      ),
  });
};


const cancelEditPurchase = () => {
  setEditingPurchaseId(null);

  setEditingPurchaseDraft({
    productName: "",
    quantity: "1",
    totalPrice: "",
    supplierName: "",
    vatInvoice: false,
  });
};


const savePurchaseEdit = async (
  purchaseId
) => {
  if (
    !ensureSystemWritable() ||
    !canEditData ||
    purchaseSaving ||
    !purchaseId
  ) {
    return;
  }

  const productName =
    String(
      editingPurchaseDraft
        .productName || ""
    ).trim();

  const supplierName =
    String(
      editingPurchaseDraft
        .supplierName || ""
    ).trim();

  const quantity =
    Number(
      editingPurchaseDraft.quantity
    );

  const totalPrice =
    Number(
      editingPurchaseDraft
        .totalPrice
    );

  if (!productName) {
    alert(
      "اكتب اسم المنتج أولاً."
    );

    return;
  }

  if (
    !Number.isFinite(quantity) ||
    quantity <= 0
  ) {
    alert(
      "الكمية يجب أن تكون أكبر من صفر."
    );

    return;
  }

  if (
    !Number.isFinite(totalPrice) ||
    totalPrice <= 0
  ) {
    alert(
      "السعر الإجمالي يجب أن يكون أكبر من صفر."
    );

    return;
  }

  setPurchaseSaving(true);
  setPurchasesError("");

  try {
    const {
      data,
      error,
    } = await supabase
      .from("purchases")
      .update({
        product_name:
          productName,

        quantity,

        total_price:
          totalPrice,

        supplier_name:
          supplierName,

        vat_invoice:
          Boolean(
            editingPurchaseDraft
              .vatInvoice
          ),
      })
      .eq(
        "id",
        purchaseId
      )
      .select(
        [
          "id",
          "purchase_date",
          "product_name",
          "quantity",
          "total_price",
          "supplier_name",
          "vat_invoice",
          "vat_amount",
          "unit_price",
          "created_by",
          "created_at",
          "updated_at",
        ].join(",")
      )
      .single();

    if (error) {
      throw error;
    }

    if (data) {
      upsertPurchaseInState(
        normalizePurchaseRecord(data)
      );
    }

    cancelEditPurchase();
  } catch (error) {
    console.error(
      "Purchase update error:",
      error
    );

    setPurchasesError(
      "تعذر تعديل عملية الشراء."
    );

    alert(
      "لم يتم حفظ تعديل عملية الشراء."
    );
  } finally {
    setPurchaseSaving(false);
  }
};


const deletePurchase = async (
  purchase
) => {
  if (
    !purchase?.id ||
    purchaseDeletingId
  ) {
    return;
  }

  if (!ensureDeleteAllowed()) {
    return;
  }

  const confirmed =
    window.confirm(
      `هل أنت متأكد من حذف عملية شراء ${
        purchase.productName || ""
      }؟`
    );

  if (!confirmed) return;

  setPurchaseDeletingId(
    purchase.id
  );

  setPurchasesError("");

  try {
    const {
      error,
    } = await supabase
      .from("purchases")
      .delete()
      .eq(
        "id",
        purchase.id
      );

    if (error) {
      throw error;
    }

    setPurchases(
      (previousPurchases) =>
        previousPurchases.filter(
          (purchaseItem) =>
            String(
              purchaseItem.id
            ) !==
            String(
              purchase.id
            )
        )
    );

    if (
      String(
        editingPurchaseId || ""
      ) ===
      String(
        purchase.id
      )
    ) {
      cancelEditPurchase();
    }
  } catch (error) {
    console.error(
      "Purchase delete error:",
      error
    );

    setPurchasesError(
      "تعذر حذف عملية الشراء."
    );

    alert(
      "لم يتم حذف عملية الشراء."
    );
  } finally {
    setPurchaseDeletingId(null);
  }
};


  const [editingId, setEditingId] = useState(null);
