  const getWebsiteTableCount =
    async (tableName) => {
      const {
        count,
        error,
      } = await supabase
        .from(tableName)
        .select("*", {
          count: "exact",
          head: true,
        });

      if (error) {
        throw new Error(
          error.message ||
            `تعذر على الموقع قراءة جدول ${tableName}.`
        );
      }

      const normalizedCount =
        Number(count || 0);

      if (
        !Number.isFinite(
          normalizedCount
        ) ||
        normalizedCount < 0
      ) {
        throw new Error(
          `أعاد الموقع عددًا غير صالح لجدول ${tableName}.`
        );
      }

      return normalizedCount;
    };

  const getAuthoritativeSupabaseTableCount =
    async (
      accessToken,
      tableName
    ) => {
      const tableResult =
        await requestBackupApi(
          accessToken,
          {
            action: "table",
            tableName,
            offset: 0,
            limit: 1,
          }
        );

      if (
        tableResult?.tableName !==
        tableName
      ) {
        throw new Error(
          `حدث عدم تطابق في اسم جدول ${tableName}.`
        );
      }

      const normalizedCount =
        Number(
          tableResult.totalCount
        );

      if (
        !Number.isFinite(
          normalizedCount
        ) ||
        normalizedCount < 0
      ) {
        throw new Error(
          `أعاد Supabase عددًا غير صالح لجدول ${tableName}.`
        );
      }

      return normalizedCount;
    };

  const checkSystemHealth =
    async () => {
      setSystemHealth({
        loading: true,
        checkedAt: "",
        rows: [],
        matchingTables: 0,
        mismatchingTables: 0,
        errorTables: 0,
        totalWebsiteRows: 0,
        totalSupabaseRows: 0,
        allMatched: false,
        fatalError: "",
      });

      try {
        const {
          data,
          error,
        } = await supabase.rpc(
          "get_paradise_table_counts"
        );

        if (error) {
          throw error;
        }

        const returnedRows =
          Array.isArray(data)
            ? data
            : [];

        const countMap =
          new Map(
            returnedRows.map(
              (row) => [
                String(
                  row.table_name ||
                    ""
                ),

                Number(
                  row.row_count ||
                    0
                ),
              ]
            )
          );

        const resultRows =
          systemHealthTables.map(
            ({
              tableName,
              label,
            }) => {
              const tableExists =
                countMap.has(
                  tableName
                );

              const tableCount =
                tableExists
                  ? Number(
                      countMap.get(
                        tableName
                      ) || 0
                    )
                  : 0;

              return {
                tableName,
                label,

                websiteCount:
                  tableExists
                    ? tableCount
                    : "غير موجود",

                supabaseCount:
                  tableExists
                    ? tableCount
                    : "غير موجود",

                difference:
                  tableExists
                    ? 0
                    : "غير متاح",

                status:
                  tableExists
                    ? "متصل بـ Supabase"
                    : "الجدول غير موجود",

                statusCode:
                  tableExists
                    ? "matched"
                    : "error",

                details:
                  tableExists
                    ? "الموقع يعتمد على هذا الجدول مباشرة داخل Supabase."
                    : "لم تُرجع Supabase بيانات هذا الجدول.",
              };
            }
          );

        const matchingTables =
          resultRows.filter(
            (row) =>
              row.statusCode ===
              "matched"
          ).length;

        const errorTables =
          resultRows.filter(
            (row) =>
              row.statusCode ===
              "error"
          ).length;

        const totalRows =
          resultRows.reduce(
            (
              total,
              row
            ) =>
              total +
              (
                typeof row.supabaseCount ===
                "number"
                  ? row.supabaseCount
                  : 0
              ),
            0
          );

        setSystemHealth({
          loading: false,

          checkedAt:
            new Date()
              .toLocaleString(
                "ar-SA",
                {
                  timeZone:
                    "Asia/Riyadh",
                }
              ),

          rows:
            resultRows,

          matchingTables,

          mismatchingTables: 0,

          errorTables,

          totalWebsiteRows:
            totalRows,

          totalSupabaseRows:
            totalRows,

          allMatched:
            matchingTables ===
              systemHealthTables.length &&
            errorTables === 0,

          fatalError: "",
        });
      } catch (error) {
        console.log(
          "System health check error:",
          error
        );

        setSystemHealth({
          loading: false,

          checkedAt:
            new Date()
              .toLocaleString(
                "ar-SA",
                {
                  timeZone:
                    "Asia/Riyadh",
                }
              ),

          rows: [],

          matchingTables: 0,

          mismatchingTables: 0,

          errorTables:
            systemHealthTables.length,

          totalWebsiteRows: 0,

          totalSupabaseRows: 0,

          allMatched: false,

          fatalError:
            error?.message ===
            "SUPER_ADMIN_REQUIRED"
              ? "هذا الفحص متاح للـ Super Admin فقط."
              : error?.message ||
                "تعذر قراءة بيانات Supabase.",
        });
      }
    };

  const checkServerHealth = async () => {
    try {
      const response = await fetch("/api/server-health", { cache: "no-store" });
      if (!response.ok) throw new Error(`Server health API ${response.status}`);
      setServerHealth(await response.json());
    } catch (error) {
      setServerHealth({
        error: "Server health needs a secure server-side API on Contabo/Coolify. React alone should not read Docker/Contabo internals directly.",
        details: error.message || String(error),
      });
    }
  };

