  const selectedGiftCardTemplate =
    giftCardTemplates.find(
      (template) => template.id === selectedGiftCardTemplateId
    ) || giftCardTemplates[0];

  const selectedGiftCardCategoryTemplates = giftCardTemplates.filter(
    (template) => template.category === selectedGiftCardCategory
  );

  const giftCardTextLabels = {
    recipient: "اسم المُهدى إليه",
    giver: "اسم المُهدي",
    service: "الخدمة أو الهدية",
    message: "النص الخاص",
  };

  const giftCardTextPlaceholders = {
    recipient: "اسم المُهدى إليه",
    giver: "اسم المُهدي",
    service: "الخدمة أو الهدية",
    message: "اكتب النص الخاص هنا",
  };

  const selectGiftCardTemplate = (
    template
  ) => {
    if (!template) {
      return;
    }

    setSelectedGiftCardCategory(
      template.category
    );

    setSelectedGiftCardTemplateId(
      template.id
    );

    setGiftCardTextSettings(
      createDefaultGiftCardTextSettings(
        template.language,
        template.messagePosition || {}
      )
    );

    if (
      selectedGiftCardTextKey ===
        "message" &&
      !template.customMessageEnabled
    ) {
      setSelectedGiftCardTextKey(
        "recipient"
      );
    }
  };

  const selectGiftCardCategory = (
    categoryId
  ) => {
    const firstTemplate =
      giftCardTemplates.find(
        (template) =>
          template.category ===
          categoryId
      );

    if (firstTemplate) {
      selectGiftCardTemplate(
        firstTemplate
      );
    }
  };

  const giftCardTextValues = {
    recipient:
      giftCardRecipient,

    giver:
      giftCardGiver,

    service:
      giftCardService,

    message:
      giftCardMessage,
  };

  const clampGiftCardValue = (
    value,
    minimum,
    maximum
  ) =>
    Math.min(
      maximum,
      Math.max(
        minimum,
        Number(value) || 0
      )
    );

  const updateGiftCardTextSetting = (
    textKey,
    nextValues
  ) => {
    setGiftCardTextSettings(
      (previousSettings) => ({
        ...previousSettings,

        [textKey]: {
          ...previousSettings[
            textKey
          ],

          ...nextValues,
        },
      })
    );
  };

  const moveGiftCardText = (
    axis,
    direction
  ) => {
    const currentSettings =
      giftCardTextSettings[
        selectedGiftCardTextKey
      ];

    if (!currentSettings) {
      return;
    }

    const movementStep = 0.5;

    if (axis === "top") {
      updateGiftCardTextSetting(
        selectedGiftCardTextKey,
        {
          top: Number(
            clampGiftCardValue(
              Number(
                currentSettings.top
              ) +
                direction *
                  movementStep,
              5,
              95
            ).toFixed(1)
          ),
        }
      );

      return;
    }

    updateGiftCardTextSetting(
      selectedGiftCardTextKey,
      {
        left: Number(
          clampGiftCardValue(
            Number(
              currentSettings.left
            ) +
              direction *
                movementStep,
            5,
            95
          ).toFixed(1)
        ),
      }
    );
  };

  const resizeGiftCardText = (
    direction
  ) => {
    const currentSettings =
      giftCardTextSettings[
        selectedGiftCardTextKey
      ];

    if (!currentSettings) {
      return;
    }

    updateGiftCardTextSetting(
      selectedGiftCardTextKey,
      {
        fontSize:
          clampGiftCardValue(
            Number(
              currentSettings.fontSize
            ) + direction,
            10,
            64
          ),
      }
    );
  };

  const toggleGiftCardTextBold =
    () => {
      const currentSettings =
        giftCardTextSettings[
          selectedGiftCardTextKey
        ];

      if (!currentSettings) {
        return;
      }

      updateGiftCardTextSetting(
        selectedGiftCardTextKey,
        {
          fontWeight:
            Number(
              currentSettings.fontWeight
            ) >= 700
              ? 400
              : 800,
        }
      );
    };

  const resetSelectedGiftCardText =
    () => {
      const defaultSettings =
        createDefaultGiftCardTextSettings(
          selectedGiftCardTemplate.language,
          selectedGiftCardTemplate.messagePosition ||
            {}
        );

      const selectedDefault =
        defaultSettings[
          selectedGiftCardTextKey
        ];

      if (!selectedDefault) {
        return;
      }

      updateGiftCardTextSetting(
        selectedGiftCardTextKey,
        selectedDefault
      );
    };

  const resetAllGiftCardText =
    () => {
      setGiftCardTextSettings(
        createDefaultGiftCardTextSettings(
          selectedGiftCardTemplate.language,
          selectedGiftCardTemplate.messagePosition ||
            {}
        )
      );
    };

  const clearGiftCardFields =
    () => {
      const shouldClear =
        window.confirm(
          "هل ترغب بمسح جميع بيانات البطاقة؟"
        );

      if (!shouldClear) {
        return;
      }

      setGiftCardRecipient("");
      setGiftCardGiver("");
      setGiftCardService("");
      setGiftCardMessage("");
      setSelectedGiftCardTextKey(
        "recipient"
      );
    };

  const calculateGiftCardWrappedLines =
    (
      context,
      text,
      maximumWidth
    ) => {
      const paragraphs =
        String(text || "").split(
          "\n"
        );

      let lineCount = 0;
      let largestWordWidth = 0;

      paragraphs.forEach(
        (paragraph) => {
          const words =
            paragraph
              .trim()
              .split(/\s+/)
              .filter(Boolean);

          if (words.length === 0) {
            lineCount += 1;
            return;
          }

          let currentLine = "";

          words.forEach((word) => {
            largestWordWidth =
              Math.max(
                largestWordWidth,
                context.measureText(
                  word
                ).width
              );

            const candidateLine =
              currentLine
                ? `${currentLine} ${word}`
                : word;

            if (
              currentLine &&
              context.measureText(
                candidateLine
              ).width >
                maximumWidth
            ) {
              lineCount += 1;
              currentLine = word;
            } else {
              currentLine =
                candidateLine;
            }
          });

          if (currentLine) {
            lineCount += 1;
          }
        }
      );

      return {
        lineCount,
        largestWordWidth,
      };
    };

  const fitGiftCardText = async (
    textKey =
      selectedGiftCardTextKey
  ) => {
    const textValue =
      String(
        giftCardTextValues[
          textKey
        ] || ""
      ).trim();

    if (!textValue) {
      return;
    }

    const currentSettings =
      giftCardTextSettings[
        textKey
      ];

    if (!currentSettings) {
      return;
    }

    if (
      typeof document !==
        "undefined" &&
      document.fonts?.ready
    ) {
      await document.fonts.ready;
    }

    const measurementCanvas =
      document.createElement(
        "canvas"
      );

    const context =
      measurementCanvas.getContext(
        "2d"
      );

    if (!context) {
      return;
    }

    const fontData =
      welcomeBoardFonts.find(
        (font) =>
          font.id ===
          currentSettings.fontId
      ) || welcomeBoardFonts[0];

    const maximumWidth =
      540 *
        (Number(
          currentSettings.width
        ) /
          100) -
      18;

    const maximumLines =
      textKey === "message"
        ? 5
        : 1;

    const minimumFontSize =
      textKey === "message"
        ? 12
        : 11;

    let nextFontSize =
      clampGiftCardValue(
        currentSettings.fontSize,
        minimumFontSize,
        64
      );

    while (
      nextFontSize >
      minimumFontSize
    ) {
      context.font =
        `${Number(
          currentSettings.fontWeight ||
            400
        )} ${nextFontSize}px ${fontData.font}`;

      const {
        lineCount,
        largestWordWidth,
      } =
        calculateGiftCardWrappedLines(
          context,
          textValue,
          maximumWidth
        );

      if (
        lineCount <=
          maximumLines &&
        largestWordWidth <=
          maximumWidth
      ) {
        break;
      }

      nextFontSize -= 1;
    }

    updateGiftCardTextSetting(
      textKey,
      {
        fontSize:
          nextFontSize,
      }
    );
  };

  const fitAllGiftCardTexts =
    async () => {
      const editableKeys = [
        "recipient",
        "giver",
        "service",
      ];

      if (
        selectedGiftCardTemplate
          .customMessageEnabled
      ) {
        editableKeys.push(
          "message"
        );
      }

      for (
        const textKey of editableKeys
      ) {
        await fitGiftCardText(
          textKey
        );
      }
    };

  const saveGiftCardImage =
    async () => {
      if (
        !giftCardRecipient.trim() ||
        !giftCardGiver.trim()
      ) {
        alert(
          "أدخلي اسم المُهدى إليه واسم المُهدي أولًا."
        );

        return;
      }

      if (
        selectedGiftCardTemplate
          .customMessageEnabled &&
        !giftCardMessage.trim()
      ) {
        alert(
          "اكتبي النص الخاص بالبطاقة أولًا."
        );

        return;
      }

      const giftCardElement =
        giftCardCanvasRef.current;

      if (!giftCardElement) {
        alert(
          "تعذر العثور على معاينة البطاقة."
        );

        return;
      }

      try {
        setGiftCardIsSaving(
          true
        );

        if (
          typeof document !==
            "undefined" &&
          document.fonts?.ready
        ) {
          await document.fonts.ready;
        }

        await new Promise(
          (resolve) => {
            requestAnimationFrame(
              () => {
                requestAnimationFrame(
                  resolve
                );
              }
            );
          }
        );

        const elementWidth =
          giftCardElement.getBoundingClientRect()
            .width;

        const captureScale =
          899 /
          Math.max(
            elementWidth,
            1
          );

        const capturedCanvas =
          await html2canvas(
            giftCardElement,
            {
              backgroundColor:
                null,

              useCORS: true,

              allowTaint:
                false,

              logging:
                false,

              imageTimeout:
                15000,

              scale:
                captureScale,
            }
          );

        const finalCanvas =
          document.createElement(
            "canvas"
          );

        finalCanvas.width =
          899;

        finalCanvas.height =
          1600;

        const finalContext =
          finalCanvas.getContext(
            "2d"
          );

        if (!finalContext) {
          throw new Error(
            "Gift card canvas context unavailable"
          );
        }

        finalContext.drawImage(
          capturedCanvas,
          0,
          0,
          899,
          1600
        );

        const safeRecipientName =
          giftCardRecipient
            .trim()
            .replace(
              /[^\p{L}\p{N}]+/gu,
              "-"
            )
            .replace(
              /^-+|-+$/g,
              ""
            ) ||
          "Gift";

        const fileName =
          `Paradise-Gift-${selectedGiftCardTemplate.id}-${safeRecipientName}-${getCurrentLocalDate()}.png`;

        const link =
          document.createElement(
            "a"
          );

        link.download =
          fileName;

        link.href =
          finalCanvas.toDataURL(
            "image/png",
            1
          );

        document.body.appendChild(
          link
        );

        link.click();
        link.remove();
      } catch (error) {
        console.log(
          "Gift card image save error:",
          error
        );

        alert(
          "تعذر حفظ بطاقة الإهداء. حاولي مرة أخرى."
        );
      } finally {
        setGiftCardIsSaving(
          false
        );
      }
    };

